{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/post-actions.json
    The calls to action of a post header: share and save side by side, one wide read button, or a wide read button with share and save as icons.
    Props (p): labels, mode. -#}
{%- set v_labels = (p.labels ?? null) -%}
{%- set v_mode = (p.mode ?? 'pair') -%}
{%- if ui_t(ui_eq(v_mode, 'pair')) %}
  {%- set c_3 -%}
    {%- set c_1 -%}
      {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'share-2', 'Size': 16}}, with_context = false) }}
      {{ ui_text(ui_get(v_labels, ['share'])) }}
    {%- endset -%}
    {{ include('ui/button/button.html.twig', {'p': {'Variant': 'default', 'Size': 'default', 'Href': '#/', 'Class': 'gap-2', 'Attrs': ui_attrs(['data-testid', 'action-primary'])}, 'children': c_1}, with_context = false) }}
    {%- set c_2 -%}
      {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'bookmark', 'Size': 16}}, with_context = false) }}
      {{ ui_text(ui_get(v_labels, ['save'])) }}
    {%- endset -%}
    {{ include('ui/button/button.html.twig', {'p': {'Variant': 'outline', 'Size': 'default', 'Href': '#/', 'Class': 'gap-2', 'Attrs': ui_attrs(['data-testid', 'post-save'])}, 'children': c_2}, with_context = false) }}
  {%- endset -%}
  {{ include('ui/group/group.html.twig', {'p': {'Gap': '2', 'Class': 'flex-wrap'}, 'children': c_3}, with_context = false) }}
{%- else %}
  {%- set c_7 -%}
    {%- set c_4 -%}
      {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'book-open', 'Size': 16}}, with_context = false) }}
      {{ ui_text(ui_get(v_labels, ['read'])) }}
    {%- endset -%}
    {{ include('ui/button/button.html.twig', {'p': {'Variant': 'default', 'Size': 'default', 'Href': '#/', 'Class': 'gap-2 flex-1', 'Attrs': ui_attrs(['data-testid', 'action-primary'])}, 'children': c_4}, with_context = false) }}
    {%- if ui_t(ui_eq(v_mode, 'icons')) %}
      {%- set c_5 -%}
        {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'share-2', 'Size': 16}}, with_context = false) }}
      {%- endset -%}
      {{ include('ui/button/button.html.twig', {'p': {'Variant': 'outline', 'Size': 'default', 'Layout': 'icon', 'AriaLabel': ui_s(ui_get(v_labels, ['share'])), 'Attrs': ui_attrs(['data-testid', 'post-share'])}, 'children': c_5}, with_context = false) }}
      {%- set c_6 -%}
        {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'bookmark', 'Size': 16}}, with_context = false) }}
      {%- endset -%}
      {{ include('ui/button/button.html.twig', {'p': {'Variant': 'outline', 'Size': 'default', 'Layout': 'icon', 'AriaLabel': ui_s(ui_get(v_labels, ['save'])), 'Attrs': ui_attrs(['data-testid', 'post-save'])}, 'children': c_6}, with_context = false) }}
    {%- endif %}
  {%- endset -%}
  {{ include('ui/group/group.html.twig', {'p': {'Gap': '2'}, 'children': c_7}, with_context = false) }}
{%- endif %}
